const leads = $('GS - Read All Leads').all().map((i) => i.json);
const activity = $('GS - Read Activity Log').all().map((i) => i.json);
const errors = $('GS - Read Errors').all().map((i) => i.json);
const configRows = $input.all();

const config = {};
for (const row of configRows) {
  const key = row.json.Key ?? row.json.key;
  const value = row.json.Value ?? row.json.value;
  if (key) config[key] = value;
}

const tz = config.DEFAULT_TIMEZONE || 'America/New_York';
const revenueTarget = Number(config.MONTHLY_REVENUE_TARGET) || 10000;

function dateInTZ(isoString, timezone) {
  if (!isoString) return null;
  try {
    return new Date(isoString).toLocaleDateString('en-CA', { timeZone: timezone });
  } catch (e) {
    return String(isoString).slice(0, 10);
  }
}

const now = new Date();
const todayStr = dateInTZ(now.toISOString(), tz);
const monthStr = todayStr.slice(0, 7);

const todaysLeads = leads.filter((l) => dateInTZ(l.created_at_utc, tz) === todayStr);
const newSubmissions = todaysLeads.length;
const aLeads = todaysLeads.filter((l) => l.lead_grade === 'A').length;
const bLeads = todaysLeads.filter((l) => l.lead_grade === 'B').length;
const cLeads = todaysLeads.filter((l) => l.lead_grade === 'C').length;

const todaysActivity = activity.filter((a) => dateInTZ(a.event_at_utc, tz) === todayStr);
const resultEmailsSent = todaysActivity.filter((a) => a.event_type === 'result_email_sent').length;
const positiveReplies = todaysActivity.filter((a) => {
  if (a.event_type !== 'reply_received') return false;
  try {
    return JSON.parse(a.details || '{}').reply_type === 'positive';
  } catch {
    return false;
  }
}).length;
const callsBooked = todaysActivity.filter((a) => a.event_type === 'booking_created').length;
// Nothing in WF-01 through WF-06 currently writes 'proposal_sent' activity - proposals are a
// manual sales-team step for now (spec 15.4 lists proposal generation as a future workflow).
// This will start counting automatically once/if that workflow exists.
const proposalCountToday = todaysActivity.filter((a) => a.event_type === 'proposal_sent').length;

const todaysErrors = errors.filter((e) => dateInTZ(e.event_at_utc, tz) === todayStr);
const resultEmailsFailed = todaysErrors.filter(
  (e) => e.workflow_name === 'WF-02 - Result Email Delivery' || String(e.error_summary || '').toLowerCase().includes('email')
).length;

const loomsPending = leads.filter((l) => l.status === 'A-level review required');
const loomsPendingCount = loomsPending.length;
const loomsOverdueCount = loomsPending.filter(
  (l) => l.next_action_at_utc && new Date(l.next_action_at_utc) < now
).length;

const proposalsToday = leads.filter(
  (l) => l.status === 'Proposal sent' && dateInTZ(l.last_activity_at_utc, tz) === todayStr
);
const proposalValueToday = proposalsToday.reduce((sum, l) => sum + (Number(l.proposal_value) || 0), 0);

const wonThisMonth = leads.filter(
  (l) => String(l.deal_status || '').toLowerCase() === 'won'
    && dateInTZ(l.last_activity_at_utc, tz).slice(0, 7) === monthStr
);
const wonRevenueThisMonth = wonThisMonth.reduce((sum, l) => sum + (Number(l.won_revenue) || 0), 0);

const terminalStatuses = ['Won', 'Lost', 'Unsubscribed', 'Invalid', 'Nurture'];
const overdueLeads = leads.filter((l) => {
  if (terminalStatuses.includes(l.status)) return false;
  if (l.suppressed === true || String(l.suppressed).toLowerCase() === 'true') return false;
  if (!l.next_action_at_utc) return false;
  const due = new Date(l.next_action_at_utc);
  return !isNaN(due.getTime()) && due < now;
});
const overdueCount = overdueLeads.length;

const openErrors = errors.filter((e) => {
  const resolved = e.resolved === true
    || String(e.resolved || '').toLowerCase() === 'true'
    || String(e.retry_status || '').toLowerCase() === 'resolved';
  return !resolved;
});
const openErrorsCount = openErrors.length;

const sourceCounts = {};
for (const l of todaysLeads) {
  const src = l.source || 'unknown';
  sourceCounts[src] = (sourceCounts[src] || 0) + 1;
}
let topSource = 'N/A';
let topSourceCount = 0;
for (const [src, count] of Object.entries(sourceCounts)) {
  if (count > topSourceCount) { topSource = src; topSourceCount = count; }
}

const weaknessCounts = {};
for (const l of todaysLeads) {
  let weakest = [];
  try { weakest = JSON.parse(l.weakest_categories || '[]'); } catch (e) { weakest = []; }
  const top = weakest[0]?.category;
  if (top) weaknessCounts[top] = (weaknessCounts[top] || 0) + 1;
}
let topWeakness = 'N/A';
let topWeaknessCount = 0;
for (const [cat, count] of Object.entries(weaknessCounts)) {
  if (count > topWeaknessCount) { topWeakness = cat; topWeaknessCount = count; }
}

const actions = [];
if (overdueCount > 0) actions.push(`${overdueCount} lead(s) have an overdue next action - review and act today.`);
if (loomsOverdueCount > 0) actions.push(`${loomsOverdueCount} A-lead Loom review(s) are overdue on SLA.`);
if (openErrorsCount > 0) actions.push(`${openErrorsCount} error(s) need review in the Errors tab.`);
if (actions.length === 0) actions.push('No urgent actions - pipeline is current.');

return [{ json: {
  date: todayStr,
  new_submissions: newSubmissions,
  a_leads: aLeads,
  b_leads: bLeads,
  c_leads: cLeads,
  result_emails_sent: resultEmailsSent,
  result_emails_failed: resultEmailsFailed,
  positive_replies: positiveReplies,
  calls_booked: callsBooked,
  looms_pending: loomsPendingCount,
  looms_overdue: loomsOverdueCount,
  proposals_sent_today: proposalCountToday,
  proposal_value_today: proposalValueToday,
  won_revenue_this_month: wonRevenueThisMonth,
  revenue_target: revenueTarget,
  overdue_next_actions: overdueCount,
  errors_requiring_attention: openErrorsCount,
  top_source: topSource,
  most_common_weakness: topWeakness,
  required_actions: actions.join(' '),
  owner_email: config.OWNER_EMAIL || ''
} }];

const s = $input.first().json;

// Matches spec 11.2's daily owner summary format. Section 8.7 also explicitly requires
// 'Result emails sent/failed' as a reported metric, even though the illustrative 11.2
// template omits a line for it - CODE - Compute Daily Summary already calculates it, so it
// is included here rather than silently computed and never shown.
const body = [
  `Date: ${s.date}`,
  '',
  `New submissions: ${s.new_submissions}`,
  `A leads: ${s.a_leads} | B leads: ${s.b_leads} | C leads: ${s.c_leads}`,
  `Result emails sent: ${s.result_emails_sent} | Failed: ${s.result_emails_failed}`,
  `Positive replies: ${s.positive_replies}`,
  `Calls booked: ${s.calls_booked}`,
  `Loom reviews pending: ${s.looms_pending}`,
  `Overdue next actions: ${s.overdue_next_actions}`,
  `Proposals sent today: ${s.proposals_sent_today} | Value: ${s.proposal_value_today}`,
  `Won revenue this month: ${s.won_revenue_this_month} / USD ${s.revenue_target} target`,
  `Errors requiring attention: ${s.errors_requiring_attention}`,
  '',
  `Top-performing source: ${s.top_source}`,
  `Most common system weakness: ${s.most_common_weakness}`,
  `Required management actions: ${s.required_actions}`
].join('\n');

return [{ json: { ...s, summary_body: body } }];
